const items = $input.all();
return items.map(item => {
  const html = item.json.data || item.json.body || '';
  const url = $('Webhook Article URL').first().json.body?.url || $('Webhook Article URL').first().json.url || '';
  const tags = $('Webhook Article URL').first().json.body?.tags || $('Webhook Article URL').first().json.tags || '';

  // Extract title from HTML
  const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  const title = titleMatch ? titleMatch[1].trim() : url;

  // Extract meta description
  const descMatch = html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i)
    || html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*name=["']description["']/i);
  const description = descMatch ? descMatch[1].trim().substring(0, 500) : '';

  // Extract og:image
  const imgMatch = html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["']/i);
  const image = imgMatch ? imgMatch[1] : '';

  return {
    json: {
      title,
      description,
      url,
      image,
      tags: tags,
      savedDate: new Date().toISOString()
    }
  };
});

